const BOOK_MEMBER_DISCOUNT_FACTOR = 0.9;
const DEFAULT_MEMBER_DISCOUNT_FACTOR = 0.95;
const SAVE10_COUPON = "SAVE10";
const SAVE10_AMOUNT = 10;

export function getPrice(p: any, isMember: boolean, coupon?: string) {
  let price = p.price;
  if (isMember) price = applyMemberDiscount(price, p.category);
  if (coupon) price = applyCoupon(price, coupon);
  return roundToCents(price);
}

function applyMemberDiscount(price: number, category: string): number {
  const factor =
    category == "books" ? BOOK_MEMBER_DISCOUNT_FACTOR : DEFAULT_MEMBER_DISCOUNT_FACTOR;
  return price * factor;
}

function applyCoupon(price: number, coupon: string): number {
  if (coupon != SAVE10_COUPON) return price;
  return Math.max(price - SAVE10_AMOUNT, 0);
}

function roundToCents(amount: number): number {
  return Math.round(amount * 100) / 100;
}

